    EmusToPoints(emu: number): number;

    /**
     * Converts the specified JSON object into the Document Builder object of the corresponding type.
     *
     * @param message - The JSON object to convert.
     * @returns readed api class element
     *
     * @example
     * ```js
     * // How do I recreate a paragraph from a JSON object in a document?
     *
     * // Save a paragraph as JSON and then rebuild it as a bold paragraph in a document.
     *
     * let paragraph = Api.CreateParagraph();
     * paragraph.AddText("This is a new paragraph");
     * let json = paragraph.ToJSON(false, true);
     * let paragraphFromJSON = Api.FromJSON(json);
     * paragraphFromJSON.SetBold(true);
     * Api.GetDocument().AddElement(0, paragraphFromJSON);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/Api/Methods/FromJSON/
     */
    FromJSON(message: object): object;

    /**
     * Returns the object by it's internal ID.
     *
     * @param id - The object internal ID.
     * @since 9.0.4
     *
     * @example
     * ```js
     * // How do I find a specific element by its ID in a document?
     *
     * // Retrieve a paragraph using its identifier and show its type and text in a document.
     *
     * const doc = Api.GetDocument();
     *
     * const paragraph = doc.GetElement(0);
     * paragraph.AddText('Original paragraph text.');
     * const internalId = paragraph.GetInternalId();
     *
     * const found = Api.GetByInternalId(internalId);
     *
     * const resultParagraph = Api.CreateParagraph();
     * resultParagraph.AddText('Found object class type: ' + found.GetClassType());
     * resultParagraph.AddLineBreak();
     * resultParagraph.AddText('Found paragraph text: ' + found.GetText());
     * doc.Push(resultParagraph);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/Api/Methods/GetByInternalId/
     */
    GetByInternalId(id: string): object;

